// Writes evals/REVIEW.md: every golden case with its expected findings, out-of-scope
// items and near-misses, quoted from the lease, so Justin can approve labels without
// reading JSON. Regenerate after any label change:  npm run labels:review
import { writeFileSync } from "node:fs";
import { loadGoldenSet } from "../src/evals/golden.js";

const golden = [...loadGoldenSet("evals/leases"), ...loadGoldenSet("evals/hard")];
const q = (s: string) => `“${s.replace(/\s+/g, " ").trim()}”`;
const out: string[] = [
  "# Golden-set label review",
  "",
  "Generated by `npm run labels:review` from `evals/leases/*.labels.json` and `evals/hard/*.labels.json` (hard set: edit `evals/hard/source/specs.ts`, then `npm run hard:build`). Don't edit by hand.",
  "To approve a case, set `\"approved\": true` in its labels file. To change a label, edit the JSON and regenerate.",
  "Label rules: docs/LABEL_POLICY.md. Severity: violation (forbidden conduct), void (unenforceable term),",
  "notice (missing disclosure), review (a person should check). Optional = arguable; not scored either way.",
  "",
  `${golden.length} cases (${golden.filter((g) => g.id.startsWith("hard-")).length} in the hard set): ${golden.filter((g) => g.split === "dev").length} dev (used for tuning), ${golden.filter((g) => g.split === "test").length} test (held out; published numbers). Approved: ${golden.filter((g) => g.approved).length}.`,
  "",
];
for (const g of golden) {
  out.push(`## ${g.id} · ${g.split}${g.approved ? " · ✅ approved" : ""}`, "", g.summary, "");
  if (g.scope === "not_residential") out.push("**Not residential**: expect no Part II findings.", "");
  out.push("**Expected findings**", "");
  if (!g.findings.length) out.push("- none");
  for (const f of g.findings)
    out.push(`- \`${f.severity}\` ${f.ruleId} (${f.citation})${f.optional ? " *(optional)*" : ""}: ${f.note}  `, `  ${f.span ? q(f.span.quote) : "*(no clause: something the lease leaves out)*"}`);
  out.push("");
  if (g.nearMisses.length) {
    out.push("**Near-misses (should NOT be flagged)**", "");
    for (const n of g.nearMisses) out.push(`- ${n.note}: ${q(n.span.quote)}`);
    out.push("");
  }
  if (g.outOfScope.length) {
    out.push("**Out of scope (should be listed, not judged)**", "");
    for (const o of g.outOfScope) out.push(`- ${o.topic}: ${q(o.span.quote)}`);
    out.push("");
  }
}
writeFileSync("evals/REVIEW.md", out.join("\n"));
console.log(`evals/REVIEW.md: ${golden.length} cases`);
